// The archive's link-preview card (1200×630), generated by `pnpm --filter @pu/site skills:og` and
// inlined at build time so it is emitted only where the archive is built.
import type { APIRoute } from 'astro';
import og from '../assets/og.png?inline';

const bytes = Buffer.from(og.slice(og.indexOf(',') + 1), 'base64');
export const GET: APIRoute = () => new Response(new Uint8Array(bytes), { headers: { 'Content-Type': 'image/png' } });
